def canonical_vendor(label: str) -> str | None:
    """块标签 → 已知 vendor 的规范名；无匹配则 None。"""
    plain = re.sub(r"（[^）]*）|\([^)]*\)", "", label).strip()
    if plain in KNOWN_VENDORS:
        # 同义合并
        aliases = {"华为昇腾": "华为", "Hugging Face": "HuggingFace"}
        return aliases.get(plain, plain)
    return None

