'### ' prefix; None for doc_top")", "+    pa.add_argument("--body", default="")", "+    pa.add_argument("--layer-code", default=None)", "+    pa.add_argument("--branch-code", default=None)", "+    g = pa.add_mutually_exclusive_group()", "+    g.add_argument("--after", help="insert after this block key")", "+    g.add_argument("--before", help="insert before this block key")", "+    pa.set_defaults(func=cmd_add_block)", "+", "+    pd = sub.add_parser("delete-block")", "+    pd.add_argument("key")", "+    pd.set_defaults(func=cmd_delete_block)", "+", "+    pr = sub.add_parser("replace")", "+    pr.add_argument("key", help="block key")", "+    pr.add_argument("--old", required=True)", "+    pr.add_argument("--new", required=True)", "+    pr.add_argument("--all", action="store_true",", "+                    help="replace all occurrences (default: require unique)")", "+    pr.set_defaults(func=cmd_replace)", "+", "+    pap = sub.add_parser("append")", "+    pap.add_argument("key", help="block key")", "+    pap.add_argument("--text", required=True)", "+    pap.set_defaults(func=cmd_append)", "+", "+    par = sub.add_parser("add-ref")", "+    par.add_argument("--citation", required=True,", "+                     help="IEEE-style citation, excluding [N] prefix")", "+    par.set_defaults(func=cmd_add_ref)", "+", "     args = p.parse_args()", "     args.func(args)", " "]}], "originalFile": null, "userModified": false}

